sp_widget.client_script:
api.controller = function($location,$window,spUtil) {

    var c = this;

    c.goToEmployee = function() {
        $location.url(
            "?id=employee_role_asean"
        );
    };

    c.goToManager = function() {
        $location.url(
            "?id=manager_role_asean"
        );
    };

    c.downloadUserGuide = function(event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        if (
            !c.data.userGuideAvailable ||
            !c.data.userGuideDownloadUrl
        ) {
            spUtil.addErrorMessage(
                "No PDF is attached to the Role Selection ASEAN widget."
            );
            return;
        }

        /*
         * Using location.href normally triggers the attachment
         * download more reliably than window.open.
         */
        $window.location.href =
            c.data.userGuideDownloadUrl;
    };

    c.toggleUserInformation = function() {
        c.data.showUserInformation =
            !c.data.showUserInformation;
    };

    c.refreshPage = function() {
        $window.location.reload();
    };

    c.handleTileKey = function(
        event,
        roleType
    ) {

        if (
            event.which !== 13 &&
            event.which !== 32
        ) {
            return;
        }

        event.preventDefault();

        if (roleType === "employee") {
            c.goToEmployee();
        }

        if (roleType === "manager") {
            c.goToManager();
        }
    };

};

sp_widget.css:
.role-selection-page {
    min-height: 100vh;
    padding: 28px 20px;
    background: #f7f7f7;
    font-family: Arial, sans-serif;
}

.role-selection-card {
    position: relative;
    max-width: 1060px;
    min-height: 650px;
    margin: 0 auto;
    padding: 22px 70px 30px;
    background: #ffffff;
    border: 1px solid #333333;
    box-shadow: 0 2px 7px rgba(0, 0, 0, 0.12);
}

.top-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 25px;
}

.notice-banner {
    display: flex;
    align-items: center;
    min-width: 540px;
    padding: 8px 14px;
    background: #eeeeee;
}

.notice-banner:hover {
    background: #e5e5e5;
}

.notice-icon {
    margin-right: 12px;
    color: #f58220;
    font-size: 35px;
}

.notice-text {
    color: #606060;
    font-size: 13px;
    line-height: 1.45;
}

.guide-download-button {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin-left: 5px;
    padding: 2px 5px;
    color: #ef6900;
    background: transparent;
    border: 0;
    font-size: 13px;
    font-weight: bold;
    cursor: pointer;
    text-decoration: underline;
}

.guide-download-button:hover,
.guide-download-button:focus {
    color: #c75300;
    outline: 1px dotted #ef6900;
}

.guide-download-button i {
    font-size: 14px;
}

.company-brand {
    position: relative;
    min-width: 180px;
    padding-right: 20px;
    text-align: right;
}

.brand-main {
    color: #009999;
    font-size: 23px;
    font-weight: bold;
}

.brand-sub {
    color: #f58220;
    font-size: 22px;
    font-weight: bold;
}

.brand-dots {
    position: absolute;
    right: 0;
    top: 18px;
    color: #f58220;
    font-size: 18px;
}

.welcome-section {
    margin-top: 15px;
    color: #3f3f3f;
}

.dear-text,
.welcome-text,
.select-role-text {
    margin-bottom: 8px;
    font-size: 29px;
}

.role-panel {
    display: flex;
    justify-content: space-around;
    gap: 65px;
    width: 78%;
    min-height: 220px;
    margin: 25px auto 0;
    padding: 20px 35px;
    border: 4px solid #1c1c1c;
}

.role-tile {
    flex: 1;
    max-width: 310px;
    min-height: 175px;
    padding: 5px 18px 15px;
    text-align: center;
    cursor: pointer;
    outline: none;
    border: 2px solid transparent;
    transition: all 0.2s ease;
}

.role-tile:hover,
.role-tile:focus {
    background: #fffaf5;
    border-color: #f58220;
    transform: translateY(-2px);
}

.role-icon {
    margin-bottom: 15px;
    color: #ef6900;
    font-size: 75px;
    line-height: 1;
}

.employee-icon {
    font-size: 68px;
}

.manager-icon {
    font-size: 76px;
}

.role-title {
    margin-bottom: 9px;
    color: #ef6900;
    font-size: 17px;
    font-weight: bold;
}

.role-description {
    margin-top: 4px;
    color: #a0a0a0;
    font-size: 14px;
    font-style: italic;
    line-height: 1.25;
}

.utility-section {
    margin-top: 15px;
}

.utility-link {
    display: flex;
    align-items: center;
    width: fit-content;
    margin-bottom: 8px;
    color: #ef6900;
    font-size: 14px;
    font-weight: bold;
    cursor: pointer;
}

.utility-link:hover {
    text-decoration: underline;
}

.utility-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 31px;
    height: 31px;
    margin-right: 10px;
    color: #ef6900;
    border: 2px solid #ef6900;
    border-radius: 50%;
    font-size: 17px;
}

.user-information-panel {
    width: 420px;
    margin-top: 15px;
    border: 1px solid #cccccc;
    background: #ffffff;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
}

.user-information-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 9px 12px;
    color: #ffffff;
    background: #f58220;
    font-weight: bold;
}

.close-information {
    padding: 0;
    color: #ffffff;
    background: transparent;
    border: 0;
    font-size: 17px;
    cursor: pointer;
}

.user-information-body {
    padding: 12px 15px;
}

.information-row {
    margin-bottom: 8px;
}

.information-label {
    display: inline-block;
    width: 85px;
    font-weight: bold;
}

.bottom-user-details {
    position: absolute;
    right: 70px;
    bottom: 28px;
    min-width: 380px;
    font-size: 14px;
}

.bottom-row {
    display: flex;
    margin-top: 5px;
}

.bottom-label {
    width: 100px;
    color: #666666;
    text-decoration: underline;
}

.bottom-value {
    color: #222222;
    font-weight: 500;
}

@media screen and (max-width: 900px) {

    .role-selection-card {
        padding: 20px;
    }

    .top-row {
        flex-direction: column;
    }

    .notice-banner {
        min-width: 0;
        width: 100%;
    }

    .company-brand {
        align-self: flex-end;
    }

    .role-panel {
        width: 100%;
        flex-direction: column;
        gap: 20px;
    }

    .role-tile {
        max-width: none;
    }

    .bottom-user-details {
        position: static;
        margin-top: 25px;
    }

    .user-information-panel {
        width: 100%;
    }
}

sp_widget.script:
(function() {

    data.userName = gs.getUserDisplayName() || "";
    data.userEmail = gs.getUser().getEmail() || "";
    data.userUserName = gs.getUserName() || "";
    data.showUserInformation = false;

    data.userGuideAvailable = false;
    data.userGuideDownloadUrl = "";
    data.userGuideFileName = "";

    /*
     * Sys ID of the Role Selection ASEAN widget.
     */
    var WIDGET_SYS_ID =
        "405a2ea247ce8310ff78de94116d4322";

    /*
     * Find the latest PDF attached to this widget.
     */
    var attachmentGR = new GlideRecord("sys_attachment");

    attachmentGR.addQuery(
        "table_name",
        "sp_widget"
    );

    attachmentGR.addQuery(
        "table_sys_id",
        WIDGET_SYS_ID
    );

    /*
     * Accept PDF content type or a filename ending in .pdf.
     */
    var pdfCondition =
        attachmentGR.addQuery(
            "content_type",
            "application/pdf"
        );

    pdfCondition.addOrCondition(
        "file_name",
        "ENDSWITH",
        ".pdf"
    );

    attachmentGR.orderByDesc("sys_created_on");
    attachmentGR.setLimit(1);
    attachmentGR.query();

    if (attachmentGR.next()) {

        data.userGuideAvailable = true;

        data.userGuideFileName =
            attachmentGR.getValue("file_name") ||
            "User Guide.pdf";

        data.userGuideDownloadUrl =
            "/sys_attachment.do?sys_id=" +
            attachmentGR.getUniqueValue();

    }

})();
